{"path": "/app/bin/payroll.py", "content": "#!/usr/bin/env python3
"""Payroll summary: python3 payroll.py INPUT_DIR OUTPUT_FILE (see /app/docs)."""
import csv
import gzip
import io
import json
import os
import sys
from datetime import date, datetime, timedelta, timezone
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


# ---------------------------------------------------------------- helpers
def read_text(path):
    with open(path, "rb") as f:
        data = f.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    text = data.decode("utf-8-sig")
    return text


def lines_of(path):
    text = read_text(path)
    return [ln for ln in text.splitlines() if ln.strip() != ""]


def from_epoch(sec):
    return int(sec)


def local_to_epoch(naive, tz, fold=0):
    """naive local datetime -> epoch seconds (int)."""
    dt = naive.replace(tzinfo=tz, fold=fold)
    return int(dt.timestamp()) if False else _dt_epoch(dt)


def _dt_epoch(dt):
    d = dt.astimezone(UTC) - EPOCH
    return d.days * 86400 + d.seconds


def iso_to_epoch(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return _dt_epoch(dt)


def std_offset_seconds(tz, epoch):
    """Standard (non-DST) UTC offset of the zone around the given instant."""
    year = datetime.fromtimestamp(epoch, UTC).year
    best = None
    for m in (1, 7):
        dt = datetime(year, m, 1, 12, tzinfo=tz)
        if not dt.dst():
            return int(dt.utcoffset().total_seconds())
        o = int(dt.utcoffset().total_seconds() - dt.dst().total_seconds())
        best = o
    return best


# ---------------------------------------------------------------- parsers
# Each parser yields (punch_id, employee, direction('IN'/'OUT'), epoch)
def parse_abbr_csv(path, tz):
    header = None
    out = []
    for row in csv.reader(io.StringIO(read_text(path))):
        if not row or all(c.strip() == "" for c in row):
            continue
        cells = [c.strip() for c in row]
        if "Badge" in cells and "Punch" in cells:
            header = cells
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        d = datetime.strptime(r["Date"], "%m/%d/%Y")
        t = r["Time"].strip().upper()
        ampm = None
        if t.endswith("AM") or t.endswith("PM"):
            ampm = t[-2:]
            t = t[:-2].strip()
        parts = t.split(":")
        h, mi = int(parts[0]), int(parts[1])
        s = int(parts[2]) if len(parts) > 2 else 0
        if ampm:
            h = h % 12
            if ampm == "PM":
                h += 12
        naive = d.replace(hour=h, minute=mi, second=s)
        zone = r.get("Zone", "").strip().upper()
        fold = 1 if zone.endswith("ST") else 0
        ep = local_to_epoch(naive, tz, fold)
        out.append((r["Record"], r["Badge"], r["Punch"].upper(), ep))
    return out


def parse_epoch_jsonl(path, tz):
    out = []
    schema = 1
    for ln in lines_of(path):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        if not isinstance(o, dict):
            continue
        if "schema" in o and "id" not in o and "punch_id" not in o:
            schema = int(o["schema"])
            continue
        if o.get("heartbeat") is True:
            continue
        if schema == 2:
            if "punch_id" not in o:
                continue
            ep = int(o["epoch_ms"]) // 1000
            out.append((str(o["punch_id"]), o["employee"], str(o["direction"]).upper(), ep))
        else:
            if "id" not in o:
                continue
            if "ts" in o and o["ts"] is not None:
                ep = int(o["ts"])
            else:
                ep = int(o["ts_ms"]) // 1000
            out.append((str(o["id"]), o["emp"], str(o["dir"]).upper(), ep))
    return out


def parse_offset_csv(path, tz):
    out = []
    header = None
    for row in csv.reader(io.StringIO(read_text(path)), delimiter=";", quotechar='"'):
        if not row or all(c.strip() == "" for c in row):
            continue
        cells = [c.strip() for c in row]
        if "punch_id" in cells and "timestamp" in cells:
            header = cells
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        d = "IN" if r["event"].lower() == "clock_in" else "OUT"
        out.append((r["punch_id"], r["employee"], d, iso_to_epoch(r["timestamp"])))
    return out


def parse_legacy_fixed(path, tz):
    out = []
    offset = None  # None -> site standard offset
    for ln in lines_of(path):
        t = ln[0]
        if t == "H":
            off = ln[13:18].strip()
            if off and off[0] in "+-" and len(off) == 5:
                sec = (int(off[1:3]) * 3600 + int(off[3:5]) * 60)
                offset = sec if off[0] == "+" else -sec
            else:
                offset = None
        elif t == "D":
            pid = ln[1:9]
            badge = ln[9:15].strip()
            direction = "IN" if ln[15] == "I" else "OUT"
            dts = ln[16:30]
            naive = datetime.strptime(dts, "%Y%m%d%H%M%S")
            as_utc = _dt_epoch(naive.replace(tzinfo=UTC))
            off = offset
            if off is None:
                off = std_offset_seconds(tz, as_utc)
            out.append((pid, "E" + badge, direction, as_utc - off))
    return out


def parse_de_tsv(path, tz):
    out = []
    header = None
    for row in csv.reader(io.StringIO(read_text(path)), delimiter="\t"):
        if not row or all(c.strip() == "" for c in row):
            continue
        cells = [c.strip() for c in row]
        if "Ausweis" in cells and "Buchung" in cells:
            header = cells
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        d = datetime.strptime(r["Datum"], "%d.%m.%Y")
        h, mi = r["Uhrzeit"].split(":")[:2]
        naive = d.replace(hour=int(h), minute=int(mi))
        fold = 1 if r["Zeitzone"].upper() == "MEZ" else 0
        ep = local_to_epoch(naive, tz, fold)
        out.append((r["Nr"], r["Ausweis"], "IN" if r["Buchung"].upper() == "K" else "OUT", ep))
    return out


def parse_local_csv(path, tz):
    out = []
    header = None
    for row in csv.reader(io.StringIO(read_text(path))):
        if not row or all(c.strip() == "" for c in row):
            continue
        cells = [c.strip() for c in row]
        if "employee_id" in cells and "punch_ref" in cells:
            header = cells
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        naive = datetime.strptime(r["local_time"], "%Y-%m-%d %H:%M:%S")
        out.append((r["punch_ref"], r["employee_id"], r["direction"].upper(), local_to_epoch(naive, tz, 0)))
    return out


def parse_local_jsonl(path, tz):
    out = []
    for ln in lines_of(path):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        p = o.get("punch") if isinstance(o, dict) else None
        if not isinstance(p, dict):
            continue
        naive = datetime.strptime(p["at"], "%Y-%m-%d %H:%M:%S")
        pid = p["id"]
        pid = str(int(pid)) if not isinstance(pid, str) else pid
        out.append((pid, p["badge"], str(p["type"]).upper(), local_to_epoch(naive, tz, 0)))
    return out


PARSERS = {
    "abbr-csv": parse_abbr_csv,
    "epoch-jsonl": parse_epoch_jsonl,
    "offset-csv": parse_offset_csv,
    "legacy-fixed": parse_legacy_fixed,
    "de-tsv": parse_de_tsv,
    "local-csv": parse_local_csv,
    "local-jsonl": parse_local_jsonl,
}


def walk_files(d):
    res = []
    if not os.path.isdir(d):
        return res
    for root, _dirs, files in os.walk(d):
        for f in files:
            res.append(os.path.join(root, f))
    return sorted(res)


# ---------------------------------------------------------------- main logic
def main(inp, outp):
    period = json.load(open(os.path.join(inp, "period.json")))
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = iso_to_epoch(period["corrections_cutoff"])

    sites = {}
    with open(os.path.join(inp, "sites.csv"), encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())

    employees = {}
    with open(os.path.join(inp, "employees.csv"), encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            employees[r["employee_id"].strip()] = r["home_site"].strip()

    rates = {}
    with open(os.path.join(inp, "rates.csv"), encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            rates.setdefault(r["employee_id"].strip(), []).append(
                (date.fromisoformat(r["effective_from"].strip()), Fraction(r["hourly_rate"].strip())))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect punches: (site, id) -> [employee, dir, epoch]
    punches = {}
    ever = set()
    for site, (tz, fmt) in sites.items():
        parser = PARSERS[fmt]
        for path in walk_files(os.path.join(inp, "exports", site)):
            for pid, emp, d, ep in parser(path, tz):
                key = (site, pid)
                ever.add(key)
                if key not in punches:
                    punches[key] = [emp.strip(), d, ep]

    # 2. corrections
    corrs = []
    for path in walk_files(os.path.join(inp, "corrections")):
        with open(path, encoding="utf-8-sig", newline="") as f:
            for r in csv.DictReader(f):
                if not r.get("correction_id"):
                    continue
                r = {k: (v or "").strip() for k, v in r.items() if k}
                corrs.append(r)
    for r in corrs:
        r["_t"] = iso_to_epoch(r["issued_at"])
    corrs = [r for r in corrs if r["_t"] <= cutoff]
    corrs.sort(key=lambda r: (r["_t"], r["correction_id"]))
    voided = set()
    applied = 0
    for r in corrs:
        key = (r["site"], r["punch_id"])
        act = r["action"].lower()
        if act == "void":
            if key in punches and key not in voided:
                voided.add(key)
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches and key not in voided and r["time"]:
                punches[key][2] = iso_to_epoch(r["time"])
                applied += 1
        elif act == "add":
            if key not in ever and r["site"] in sites and r["time"]:
                ever.add(key)
                punches[key] = [r["employee"], r["type"].upper(), iso_to_epoch(r["time"])]
                applied += 1

    # discard unknown badges
    byemp = {}
    for (site, pid), (emp, d, ep) in punches.items():
        if emp in employees:
            byemp.setdefault(emp, []).append((ep, 0 if d == "OUT" else 1, site, pid, d))

    def round_epoch(ep, tz):
        off = int(datetime.fromtimestamp(ep, UTC).astimezone(tz).utcoffset().total_seconds())
        r = (ep + off) % 360
        return ep - r if r < 180 else ep + (360 - r)

    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0}
    per_emp_shifts = {e: [] for e in employees}

    def workday(ep, htz):
        return datetime.fromtimestamp(ep, UTC).astimezone(htz).date()

    for emp, lst in byemp.items():
        htz = sites[employees[emp]][0] if employees[emp] in sites else UTC
        lst.sort()
        kept = []
        last = None
        for item in lst:
            ep, _o, site, pid, d = item
            rep = round_epoch(ep, sites[site][0])
            if last is not None and last[4] == d and ep - last[0] <= 300:
                if pstart <= workday(rep, htz) <= pend:
                    exc["duplicates_dropped"] += 1
                continue
            last = item
            kept.append((item, rep))
        pending = None
        shifts = []

        def count(kind, rep):
            if pstart <= workday(rep, htz) <= pend:
                exc[kind] += 1

        for item, rep in kept:
            d = item[4]
            if d == "IN":
                if pending is not None:
                    count("open_shifts", pending[1])
                pending = (item, rep)
            else:
                if pending is None:
                    count("orphan_outs", rep)
                elif rep - pending[1] <= 16 * 3600:
                    shifts.append((pending, (item, rep)))
                    pending = None
                else:
                    count("open_shifts", pending[1])
                    count("orphan_outs", rep)
                    pending = None
        if pending is not None:
            count("open_shifts", pending[1])

        for (iin, rin), (iout, rout) in shifts:
            wd = workday(rin, htz)
            if not (pstart <= wd <= pend):
                continue
            tz = sites[iin[2]][0]
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(rin, rout, tz), paid)
            per_emp_shifts[emp].append({"in": rin, "wd": wd, "paid": paid, "night": night})

    result_emps = {}
    tot = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    tot_gross = 0
    for emp in sorted(employees):
        sh = sorted(per_emp_shifts[emp], key=lambda s: s["in"])
        day_used = {}
        week_used = {}
        ot_total = 0
        pay = Fraction(0)
        for s in sh:
            du = day_used.get(s["wd"], 0)
            daily_ot = max(0, du + s["paid"] - 480) - max(0, du - 480)
            day_used[s["wd"]] = du + s["paid"]
            nonday = s["paid"] - daily_ot
            wk = s["wd"] - timedelta(days=s["wd"].weekday())
            wu = week_used.get(wk, 0)
            weekly_ot = max(0, wu + nonday - 2400) - max(0, wu - 2400)
            week_used[wk] = wu + nonday
            ot = daily_ot + weekly_ot
            reg = s["paid"] - ot
            s["ot"] = ot
            ot_total += ot
            rate = None
            for eff, rt in rates.get(emp, []):
                if eff <= s["wd"]:
                    rate = rt
            if rate is None:
                rate = Fraction(0)
            pay += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * s["night"] / 60
        cents = (pay * 100 + Fraction(1, 2)).__floor__()
        gross = "%d.%02d" % divmod(cents, 100)
        e = {
            "shifts": len(sh),
            "paid_minutes": sum(s["paid"] for s in sh),
            "overtime_minutes": ot_total,
            "night_minutes": sum(s["night"] for s in sh),
            "gross": gross,
        }
        result_emps[emp] = e
        tot["shifts"] += e["shifts"]
        tot["paid_minutes"] += e["paid_minutes"]
        tot["overtime_minutes"] += e["overtime_minutes"]
        tot["night_minutes"] += e["night_minutes"]
        tot_gross += cents

    tot["gross"] = "%d.%02d" % divmod(tot_gross, 100)
    exc["corrections_applied"] = applied
    out = {
        "period": {"start": period["start"], "end": period["end"]},
        "employees": result_emps,
        "exceptions": exc,
        "totals": tot,
    }
    d = os.path.dirname(os.path.abspath(outp))
    os.makedirs(d, exist_ok=True)
    with open(outp, "w") as f:
        json.dump(out, f, indent=1)


def night_minutes(rin, rout, tz):
    if rout <= rin:
        return 0
    first = datetime.fromtimestamp(rin, UTC).astimezone(tz).date() - timedelta(days=1)
    last = datetime.fromtimestamp(rout, UTC).astimezone(tz).date()
    total = 0
    d = first
    while d <= last:
        a = _dt_epoch(datetime(d.year, d.month, d.day, 22, tzinfo=tz))
        n = d + timedelta(days=1)
        b = _dt_epoch(datetime(n.year, n.month, n.day, 6, tzinfo=tz))
        lo, hi = max(a, rin), min(b, rout)
        if hi > lo:
            total += hi - lo
        d += timedelta(days=1)
    return total // 60


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
